using EventLensAI.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace EventLensAI.Infrastructure.Persistence.Configurations;
internal sealed class CapturedMediaConfiguration:IEntityTypeConfiguration<CapturedMedia>{public void Configure(EntityTypeBuilder<CapturedMedia>b){b.ToTable("captured_media");b.ConfigureBase();b.Property(x=>x.CaptureMode).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.FileName).HasMaxLength(255);b.Property(x=>x.FilePath).HasMaxLength(500);b.Property(x=>x.MimeType).HasMaxLength(100);b.HasIndex(x=>x.OrganizationId);b.HasIndex(x=>x.EventId);b.HasIndex(x=>x.SessionId);b.HasIndex(x=>x.CaptureMode);b.HasIndex(x=>x.CreatedAt);b.HasOne<Organization>().WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Event>().WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.Restrict);b.HasOne<BoothSession>().WithMany().HasForeignKey(x=>x.SessionId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class MediaCaptureSettingsConfiguration:IEntityTypeConfiguration<MediaCaptureSettings>{public void Configure(EntityTypeBuilder<MediaCaptureSettings>b){b.ToTable("media_capture_settings");b.ConfigureBase();b.Property(x=>x.Quality).HasPrecision(4,3);b.HasIndex(x=>new{x.OrganizationId,x.EventId}).IsUnique().HasFilter("[IsDeleted] = 0");b.HasOne<Organization>().WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Event>().WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class MediaProcessingJobConfiguration:IEntityTypeConfiguration<MediaProcessingJob>{public void Configure(EntityTypeBuilder<MediaProcessingJob>b){b.ToTable("media_processing_jobs");b.ConfigureBase();b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.ErrorCode).HasMaxLength(100);b.HasIndex(x=>x.OrganizationId);b.HasIndex(x=>x.CapturedMediaId);b.HasIndex(x=>x.Status);b.HasOne<Organization>().WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<CapturedMedia>().WithMany().HasForeignKey(x=>x.CapturedMediaId).OnDelete(DeleteBehavior.Restrict);}}
